import {mountDomains,renderCourse} from './course-ui.js';
import {createQLearner,trainEpisode,evaluateGreedy,transition,grid} from './rl-math.js';
import {concepts,chapters} from './course.js';
import {draw,hero,colors} from './visuals.js';
import {trainingStep,trainData,mean} from './math.js';
const $=id=>document.getElementById(id);
const storageKey='neuro-atlas-v1';
let record={mastered:[],saved:[],visited:[]};
try{const stored=JSON.parse(localStorage.getItem(storageKey));if(stored&&typeof stored==='object')for(const key of Object.keys(record))if(Array.isArray(stored[key]))record[key]=stored[key].filter(n=>Number.isInteger(n)&&n>=1&&n<=concepts.length)}catch{}
let view='foundations';
let filter=-1,onlySaved=false,paused=matchMedia('(prefers-reduced-motion: reduce)').matches,active=null,params={},cards=[],autoTrain=false,labState={seed:1},elapsed=0,lastFrame=0,lastTrain=0,lastMiniTrain=0;
const resetTraining=()=>({w:-.5,b:0,step:0,loss:mean(trainData.map(([x,y])=>(-.5*x-y)**2)),history:[mean(trainData.map(([x,y])=>(-.5*x-y)**2))]});
let miniTraining=resetTraining();
const miniQL=createQLearner();for(let i=0;i<250;i++)trainEpisode(miniQL);
function save(){try{localStorage.setItem(storageKey,JSON.stringify(record))}catch{toast('浏览器未允许保存，当前会话仍可继续学习。')}updateProgress()}
function toast(msg){$('toast').textContent=msg;$('toast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('toast').classList.remove('show'),2600)}
function updateProgress(){$('savedCount').textContent=record.saved.length;$('progressText').textContent=record.mastered.length+' / '+concepts.length;$('progressBar').style.width=record.mastered.length/concepts.length*100+'%';$('progressBtn').title=`已理解 ${record.mastered.length} / ${concepts.length} 个概念`}
function makeFilters(){
 const items=view==='domain'?[['全部经典算法',-2],...chapters.slice(6).map((c,i)=>[c.name,6+i])]:[['全部基础实验',-1],...chapters.slice(0,6).map((c,i)=>[c.name,i])];
 $('filters').innerHTML=items.map(([name,i])=>`<button class="filter ${filter===i?'active':''}" data-filter="${i}">${name}</button>`).join('');
 $('chapterNav').innerHTML=chapters.slice(0,6).map((c,i)=>`<button class="chapter-nav ${filter===i?'selected':''}" data-filter="${i}" style="--chapter:${c.color}"><i></i>${c.name}<small>${concepts.filter(d=>d.chapter===i).length.toString().padStart(2,'0')}</small></button>`).join('');
}
function selectFilter(i){view=i>=6||i===-2?'domain':'foundations';filter=i;onlySaved=false;makeFilters();renderCards();setNav(view==='domain'?'domainNav':'allNav')}
function setNav(id){document.querySelectorAll('.side-link').forEach(el=>el.classList.toggle('active',el.id===id))}
const visible=new Set();const observer=new IntersectionObserver(entries=>{entries.forEach(e=>e.isIntersecting?visible.add(e.target):visible.delete(e.target))},{rootMargin:'120px'});
function renderCards(){observer.disconnect();visible.clear();const q=$('searchInput').value.trim().toLowerCase(),list=concepts.filter(c=>(onlySaved || (q&&filter<0) || (view==='domain'?c.id>28:c.id<=28))&&(filter<0||c.chapter===filter)&&(!onlySaved||record.saved.includes(c.id))&&`${c.title} ${c.en} ${c.tags}`.toLowerCase().includes(q));$('mapTitle').firstChild.textContent=onlySaved?'留住你的好奇心':filter<0?(view==='domain'?'经典算法 · 从机制走向训练':'从一颗神经元，走向整个网络'):chapters[filter].name+' · '+chapters[filter].desc;$('resultCount').textContent=list.length+' 个条目';$('cards').innerHTML=list.map(c=>`<button class="card" data-id="${c.id}" style="--accent:${chapters[c.chapter].color}" aria-label="进入${c.title}交互实验"><div class="card-top"><span class="card-id">${String(c.id).padStart(2,'0')} /</span><span class="card-level">${chapters[c.chapter].name}</span></div><h3>${c.title}</h3><div class="english">${c.en}</div><canvas aria-hidden="true"></canvas><p class="card-desc">${c.desc}</p><div class="card-bottom"><span class="${record.mastered.includes(c.id)?'done':''}">${record.mastered.includes(c.id)?'✓ 已理解':record.saved.includes(c.id)?'☆ 已收藏':'↳ 点击，动手试试'}</span><span class="arrow">↗</span></div></button>`).join('');cards=list.map(c=>{const node=$('cards').querySelector(`[data-id="${c.id}"]`);observer.observe(node);return {c,node,canvas:node.querySelector('canvas')}});$('empty').hidden=!!list.length;cards.forEach(({c,canvas})=>draw(canvas,c.id,miniParams(c.id,elapsed),elapsed,true,{seed:Math.floor(elapsed),training:miniTraining,qlearning:miniQL}));}
function miniParams(id,t){switch(id){case 1:return {w:.7+.35*Math.sin(t),v:.4,b:0};case 3:return {x:2*Math.sin(t*.5),b:.2};case 4:return {kind:'ReLU',x:3*Math.sin(t*.7)};case 5:return {pred:3+2*Math.sin(t*.8)};case 7:return {lr:.18};case 8:return {lr:.15};case 9:return {ratio:60+Math.round(Math.sin(t*.4)*2)*5};case 11:return {degree:[2,3,7,9][Math.floor(t/4)%4]};case 12:return {lambda:[0,.01,.05,.3][Math.floor(t/4)%4]};case 15:return {shift:4+Math.sin(t*.7)*3,scale:1};case 16:return {word:['猫','狗','苹果','梨'][Math.floor(t/2)%4]};case 17:return {query:['猫','喜欢','鱼'][Math.floor(t/3)%3]};case 19:return {x:1+Math.sin(t)*.5,a:.2};case 22:case 24:return {gamma:.5+.45*Math.sin(t*.4)**2};case 23:return {theta:3*Math.sin(t*.5)};case 25:return {epsilon:.1+.8*Math.sin(t*.3)**2};case 26:return {reward:Math.sin(t*.5),gamma:.9};case 29:return {a:.1+.1*Math.sin(t),depth:4};case 30:return {patch:Math.floor(t/3)%2?'4':'2'};case 31:return {query:Math.floor(t)%5,causal:'开启'};case 32:return {position:Math.floor(t)%5};case 33:return {mu:1+Math.sin(t*.5),threshold:1};case 34:return {alpha:.1+.8*Math.sin(t*.4)**2};case 35:return {nextq:2+Math.sin(t*.5)};case 36:return {ratio:1+.5*Math.sin(t*.5),adv:1,epsilon:.2};case 37:return {layers:1+Math.floor(t/3)%4};case 38:return {sharp:2*Math.sin(t*.4)};case 39:return {forget:.5+.45*Math.sin(t*.4)**2,input:.3};case 40:return {layers:1+Math.floor(t/3)%4,base:2};case 41:return {path:['A A _ B B _','A _ A B B _'][Math.floor(t/3)%2]};case 42:return {temperature:.2+.6*Math.sin(t*.5)**2};default:return {}}}
function openLab(id){active=concepts.find(c=>c.id===id);if(!active)return;params={};for(const control of active.controls)params[control[0]]=Array.isArray(control[2])?control[3]:control[5];labState={seed:1,training:resetTraining(),qlearning:createQLearner(),agent:{pos:grid.start,last:null}};autoTrain=false;$('labEyebrow').textContent=`EXPERIMENT ${String(id).padStart(2,'0')} / ${concepts.length} · ${chapters[active.chapter].name}`;$('labTitle').textContent=active.title;$('intuition').textContent=active.intuition;$('steps').innerHTML=active.steps.map(s=>`<li>${s}</li>`).join('');$('formula').textContent=active.formula;$('demoNote').textContent=active.note??'拖动参数会改变实际计算结果；流动的光点用于提示计算方向。';$('sourceLink').href=active.source;$('quizQuestion').textContent=active.quiz[0];$('quizOptions').innerHTML=active.quiz[1].map((s,i)=>`<button data-answer="${i}">${String.fromCharCode(65+i)}. ${s}</button>`).join('');$('quizFeedback').textContent=record.mastered.includes(id)?'✓ 你已经通过这个概念的小测，也可以再试一次。':'';$('labProgress').textContent=`概念 ${String(id).padStart(2,'0')} / ${concepts.length} · ${record.mastered.includes(id)?'已理解':'动手尝试后做一道小测'}`;renderControls();renderActions();updateBookmark();renderCourse(active,openLab);if(!record.visited.includes(id)){record.visited.push(id);save()}if(!$('labDialog').open)$('labDialog').showModal();$('labDialog').scrollTop=0;updateLab();}
function renderControls(){$('controls').innerHTML=active.controls.map(([key,label,min,max,step,value])=>Array.isArray(min)?`<label class="control"><span>${label}</span><select data-param="${key}" aria-label="${label}">${min.map(v=>`<option ${params[key]===v?'selected':''}>${v}</option>`).join('')}</select></label>`:`<label class="control"><span>${label}</span><input type="range" min="${min}" max="${max}" step="${step}" value="${params[key]}" data-param="${key}" aria-label="${label}"><output id="out-${key}">${params[key]}</output></label>`).join('')}
function updateLab(){if(!active||!$('labDialog').open)return;const text=draw($('labCanvas'),active.id,params,elapsed,false,labState);if($('labReadout').textContent!==text)$('labReadout').textContent=text;}
function renderBaseActions(){$('actionRow').innerHTML=active.id===20?`<button data-action="step">单步更新 +1</button><button data-action="auto">${autoTrain?'暂停训练':'自动训练 ▶'}</button><button data-action="reset">重置参数 ↺</button>`:active.id===18?'<button data-action="sample">重新采样 ↺</button>':'';}
function updateBookmark(){$('bookmarkBtn').textContent=record.saved.includes(active.id)?'★':'☆';$('bookmarkBtn').setAttribute('aria-label',record.saved.includes(active.id)?'取消收藏':'收藏此概念')}
function closeLab(){$('labDialog').close()}
function route(){showInfo(`<div class="eyebrow">YOUR LEARNING PATH</div><h2 id="infoTitle">一条循序渐进的探索路线</h2><p>每章先观察动画，再选择一个实验。通过小测后，知识地图会留下“已理解”的标记。没有锁定关卡，你可以随时跳到好奇的地方。</p>${chapters.map((c,i)=>`<button class="route-row" data-route="${i}"><b>0${i+1}</b><span>${c.name}<small>${c.desc} · ${concepts.filter(d=>d.chapter===i).length} 个概念</small></span><i>→</i></button>`).join('')}<p>推荐顺序：认识网络 → 让网络学习 → 训练的艺术 → 让网络看见 → 走向现代网络。第 20 个实验把一次训练的所有环节串起来；完成基础后，可从领域导航进入 14 门经典算法专题。</p>`)}
function showInfo(html){$('infoContent').innerHTML=html;if(!$('infoDialog').open)$('infoDialog').showModal()}
function guide(){showInfo('<div class="eyebrow">A SMALL GUIDE</div><h2 id="infoTitle">把好奇变成理解</h2><h3>01 · 看见原理</h3><p>知识地图上的动画会持续运行。用分类和搜索找到你关心的概念；右上角可以暂停或恢复全部动画。</p><h3>02 · 亲自改变它</h3><p>点击卡片进入实验。拖动滑块、切换选项，比较图形和数值。计算公式与实验的简化条件都在图下方。</p><h3>03 · 检验你的直觉</h3><p>每个概念都有一道理解小测。答对后标记为已理解；答错后有解释，可以继续尝试。收藏与进度只存储在当前浏览器，清除浏览器数据后会丢失。</p><h3>照顾你的节奏</h3><p>按 Esc 关闭实验，按 / 搜索。系统开启“减少动态效果”时，动画默认暂停，仍可调参数和单步训练。</p>')}
function sources(){showInfo(`<div class="eyebrow">CONTENT & REFERENCES</div><h2 id="infoTitle">看见，也要算得明白。</h2><p>这是面向初学者的交互教学原型。${concepts.length} 个实验使用浏览器内计算和明确标注的示意数据；它们用于建立直觉，不能代替完整课程或真实模型评估。</p><h3>内容参考</h3><p><a href="https://developers.google.com/machine-learning/crash-course" target="_blank" rel="noopener">Google · Machine Learning Crash Course ↗</a><br>神经元、激活、损失、梯度、泛化与嵌入等基础概念。</p><p><a href="https://docs.pytorch.org/docs/stable/nn.html" target="_blank" rel="noopener">PyTorch · torch.nn 官方文档 ↗</a><br>张量、卷积、池化、Dropout 与注意力等算子定义。每个实验也附有对应原始参考。</p><p><a href="https://arxiv.org/abs/1512.03385" target="_blank" rel="noopener">He et al. · Deep Residual Learning for Image Recognition ↗</a><br>残差连接的论文来源。</p><h3>强化学习参考</h3><p><a href="https://spinningup.openai.com/en/latest/spinningup/rl_intro.html" target="_blank" rel="noopener">OpenAI Spinning Up · 强化学习基础 ↗</a><br>策略、回报、状态价值与 Bellman 关系。</p><p><a href="https://gymnasium.farama.org/tutorials/training_agents/frozenlake_q_learning/" target="_blank" rel="noopener">Gymnasium · 表格 Q-learning 教程 ↗</a><br>环境交互、探索与利用、Q-learning 更新。浏览器迷宫采用自行实现的确定性教学网格。</p><p>强化学习实验在浏览器 CPU 上运行，不连接本机 CUDA 环境；Q-learning 评估时关闭探索并冻结 Q 表。</p><h3>演示边界</h3><p>嵌入位置与 Q/K/V 是手工教学示例；多项式数据、训练循环数据均为合成数据。地图光点表示计算方向，训练实验实际执行参数更新。卷积采用深度学习常用的互相关约定。</p><h3>视觉参考</h3><p>参考你提供的“深度学习 10 个基础概念”截图与文字描述，扩展为动态地图和交互实验。抖音短链接未能直接读取，未验证视频播放效果。</p>`)}
$('filters').addEventListener('click',e=>{const b=e.target.closest('[data-filter]');if(b)selectFilter(Number(b.dataset.filter))});$('chapterNav').addEventListener('click',e=>{const b=e.target.closest('[data-filter]');if(b){selectFilter(Number(b.dataset.filter));$('knowledgeMap').scrollIntoView()}});$('cards').addEventListener('click',e=>{const b=e.target.closest('[data-id]');if(b)openLab(Number(b.dataset.id))});$('searchInput').addEventListener('input',renderCards);
$('controls').addEventListener('input',e=>{const key=e.target.dataset.param;if(!key)return;params[key]=e.target.tagName==='SELECT'?e.target.value:Number(e.target.value);if(active?.id===27)labState.evaluation=null;const out=$('out-'+key);if(out)out.value=e.target.value;updateLab()});
$('quizOptions').addEventListener('click',e=>{const b=e.target.closest('[data-answer]');if(!b)return;const correct=Number(b.dataset.answer)===active.quiz[2];$('quizOptions').querySelectorAll('button').forEach(el=>el.className='');b.className=correct?'correct':'wrong';$('quizFeedback').style.color=correct?colors.lime:colors.orange;$('quizFeedback').textContent=(correct?'✓ 理解得很棒。':'再想一想。')+active.quiz[3];if(correct&&!record.mastered.includes(active.id)){record.mastered.push(active.id);save();$('labProgress').textContent=`✓ ${active.title} · 已理解`;toast('探索进度 +1 · 一点点，连接成理解。');renderCards()}});
$('actionRow').addEventListener('click',e=>{const a=e.target.dataset.action;if(a==='step'){trainingStep(labState.training,params.lr);updateLab()}if(a==='auto'){autoTrain=!autoTrain;renderActions()}if(a==='reset'){labState.training=resetTraining();autoTrain=false;renderActions();updateLab()}if(a==='sample'){labState.seed++;updateLab()}});
$('bookmarkBtn').onclick=()=>{const i=record.saved.indexOf(active.id);if(i<0)record.saved.push(active.id);else record.saved.splice(i,1);save();updateBookmark();renderCards();toast(i<0?'已加入我的收藏':'已取消收藏')};
$('closeLab').onclick=closeLab;$('labDialog').addEventListener('close',()=>{autoTrain=false;active=null});$('nextBtn').onclick=()=>openLab(active.id===concepts.length?1:active.id+1);
$('closeInfo').onclick=()=>$('infoDialog').close();$('infoContent').addEventListener('click',e=>{const b=e.target.closest('[data-route]');if(b){$('infoDialog').close();selectFilter(Number(b.dataset.route));$('knowledgeMap').scrollIntoView()}});
$('allNav').onclick=()=>{$('searchInput').value='';selectFilter(-1);$('knowledgeMap').scrollIntoView()};$('savedNav').onclick=()=>{onlySaved=true;filter=-1;$('searchInput').value='';makeFilters();renderCards();setNav('savedNav');$('knowledgeMap').scrollIntoView()};$('clearBtn').onclick=()=>{$('searchInput').value='';selectFilter(-1)};
$('pathNav').onclick=route;$('routeBtn').onclick=route;$('helpBtn').onclick=guide;$('sourcesBtn').onclick=sources;$('startBtn').onclick=()=>openLab(1);$('exploreBtn').onclick=()=>$('knowledgeMap').scrollIntoView();$('randomBtn').onclick=()=>openLab(1+Math.floor(Math.random()*concepts.length));$('progressBtn').onclick=()=>showInfo(`<div class="eyebrow">YOUR EXPLORATION</div><h2 id="infoTitle">你已理解 ${record.mastered.length} / ${concepts.length} 个概念</h2><p>已探索 ${record.visited.length} 个实验，收藏 ${record.saved.length} 个概念。通过概念小测后，理解进度才会增加。</p><p>${record.mastered.length?record.mastered.map(id=>concepts[id-1].title).join(' · '):'从一颗神经元开始：观察、调参数，再回答一道问题。'}</p><p>进度仅保存在当前浏览器，暂不支持跨设备同步。</p>`);
function setMotionButton(){$('motionBtn').textContent=paused?'▷':'Ⅱ';$('motionBtn').setAttribute('aria-label',paused?'恢复全部动画':'暂停全部动画');$('motionBtn').title=paused?'恢复全部动画':'暂停全部动画';$('stageStatus').textContent=paused?'动画已暂停 · 参数仍可调节':'实时计算'}setMotionButton();$('motionBtn').onclick=()=>{paused=!paused;setMotionButton();toast(paused?'动画已暂停，参数仍可手动调节':'动画已恢复')};
document.addEventListener('keydown',e=>{if(e.key==='/'&&!$('labDialog').open&&!$('infoDialog').open&&!['INPUT','TEXTAREA','SELECT'].includes(e.target.tagName)){e.preventDefault();$('searchInput').focus()}});window.addEventListener('resize',()=>{cards.forEach(({c,canvas})=>draw(canvas,c.id,miniParams(c.id,elapsed),elapsed,true,{training:miniTraining,qlearning:miniQL}));hero($('heroCanvas'),elapsed);updateLab()});
let lastTick=0;function frame(now){requestAnimationFrame(frame);if(now-lastFrame<33)return;const dt=lastFrame?Math.min((now-lastFrame)/1000,.1):0;lastFrame=now;if(document.hidden)return;if(!paused)elapsed+=dt;if(!paused||!lastTick){hero($('heroCanvas'),elapsed);if(elapsed-lastMiniTrain>.15){if(miniTraining.step>=120)miniTraining=resetTraining();trainingStep(miniTraining,.15);lastMiniTrain=elapsed}if(!$('labDialog').open)for(const {c,node,canvas}of cards)if(visible.has(node))draw(canvas,c.id,miniParams(c.id,elapsed),elapsed,true,{seed:Math.floor(elapsed),training:miniTraining,qlearning:miniQL});updateLab();lastTick=now}if(active?.id===27&&autoTrain&&!paused&&now-lastTrain>150){if(labState.qlearning.episodes<2000){trainEpisode(labState.qlearning,params);labState.evaluation=null;updateLab()}else{autoTrain=false;renderActions()}lastTrain=now}if(active?.id===20&&autoTrain&&!paused&&now-lastTrain>100){if(labState.training.step<1000){trainingStep(labState.training,params.lr);updateLab()}else{autoTrain=false;renderActions();toast('已完成 1000 次更新，可重置后继续探索。')}lastTrain=now}}
function renderActions(){
  if(active.id===21){$('actionRow').innerHTML='<button data-rl-action="move">执行动作 →</button><button data-rl-action="restart">回到起点 ↺</button>';return}
  if(active.id===27){$('actionRow').innerHTML=`<button data-rl-action="train">训练 20 回合</button><button data-rl-action="auto">${autoTrain?'暂停训练':'自动训练 ▶'}</button><button data-rl-action="eval">评估策略</button><button data-rl-action="reset">重置 Q 表</button>`;return}
  if(active.id===28){$('actionRow').innerHTML='<button data-rl-action="sample">重新采样 ↺</button>';return}
  renderBaseActions();
}
$('actionRow').addEventListener('click',e=>{
  const action=e.target.dataset.rlAction;if(!action)return;
  if(action==='move'){
    const current=labState.agent.pos;
    if(current===grid.goal||grid.pits.includes(current)){toast('本回合已经终止，点击“回到起点”再试一次。');return}
    const a=['向上','向右','向下','向左'].indexOf(params.action),tr=transition(current,a);
    labState.agent={pos:tr.next,last:{s:current,a,...tr}};
  }
  if(action==='restart')labState.agent={pos:grid.start,last:null};
  if(action==='train'){for(let i=0;i<20;i++)trainEpisode(labState.qlearning,params);labState.evaluation=null}
  if(action==='auto'){autoTrain=!autoTrain;renderActions()}
  if(action==='eval'){autoTrain=false;labState.evaluation=evaluateGreedy(labState.qlearning);renderActions()}
  if(action==='reset'){autoTrain=false;labState.qlearning=createQLearner();labState.evaluation=null;renderActions()}
  if(action==='sample')labState.seed++;
  updateLab();
});
mountDomains(i=>{selectFilter(i<0?-2:6+i);$('knowledgeMap').scrollIntoView()},openLab);
$('domainNav').onclick=()=>{$('domainSection').scrollIntoView();setNav('domainNav')};
updateProgress();makeFilters();renderCards();hero($('heroCanvas'),0);requestAnimationFrame(frame);
